    "answered_by": "live-marker",
    "reason": "Ownership is determined by reading the marker stamped on the live resource itself (Kubernetes labels: chant.intentius.io/stack + app.kubernetes.io/managed-by). The snapshot is never consulted; it can be deleted with no effect on ownership queries."
  },
  "q3": "newly-observed",
  "q4": {
    "action": "adopt",
    "reason": "An undeclared, live resource with no ownership marker is classified 'adopt'—a candidate for source adoption. Delete is only proposed when the live marker confirms the resource belongs to this stack."
  },
  "q5": {
    "calls_cloud": false,
    "reason": "chant build is pure synthesis: it reads .ts source and writes manifests only. No AWS or Kubernetes API calls occur, no credentials are consulted. Network access is strictly a lifecycle operation."
  },
  "q6": {
    "requires_controller_reconcile": false,
    "reason": "Snapshot only requires that declared entities exist and be readable through the provider's read API. For Kubernetes, objects must be GET-able via the API server. CAPI/CAPA, ACK, and Flux controllers need not have reconciled actual infrastructure."
  },
  "q7": {
    "specific_to_k8s_lexicon": true,
    "reason": "The k8s lexicon's describeResources() records only identity-depth attributes (namespace, labels, resourceVersion, conditions)—no reference-catalog enrichment. Thus k8s --at/--live graphs have zero edges. The AWS lexicon has the enrichment needed to resolve live references."
  }
}
